{"file_text": "@page "/apply"
@rendermode InteractiveServer
@namespace sv_06071f586ff1469c9b112c26582aa00b.Components.Pages.Apply
@using sv_06071f586ff1469c9b112c26582aa00b.Models

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    @if (currentStep == 0)
    {
        @* Step 1: Personal Info *@
        <section class="step-content">
            <h2>Personal Information</h2>

            <div class="form-group">
                <label>Full Name *</label>
                <input type="text" @bind="fullName" />
            </div>

            <div class="form-group">
                <label>Email *</label>
                <input type="email" @bind="email" />
            </div>

            <div class="form-group">
                <label>Phone *</label>
                <input type="tel" @bind="phone" />
            </div>

            <div class="form-group">
                <label>Address *</label>
                <textarea rows="2" @bind="address"></textarea>
            </div>

            <div class="step-buttons">
                <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                    @(isValidating ? "Validating..." : "Next")
                </button>
            </div>
        </section>
    }
    else if (currentStep == 1)
    {
        @* Step 2: Work History *@
        <section class="step-content">
            <h2>Work History</h2>

            @for (int i = 0; i < workEntries.Count; i++)
            {
                var idx = i;
                <WorkEntryForm Entry="@workEntries[idx]"
                               Index="idx"
                               ShowRemove="@(workEntries.Count > 1)"
                               OnEntryChanged="e => UpdateWorkEntry(idx, e)"
                               OnRemove="() => RemoveWorkEntry(idx)" />
            }

            <button type="button" class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>

            <div class="step-buttons">
                <button class="btn-back" @onclick="() => currentStep--">Back</button>
                <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </section>
    }
    else if (currentStep == 2)
    {
        @* Step 3: References *@
        <section class="step-content">
            <h2>References</h2>

            @for (int i = 0; i < references.Count; i++)
            {
                var idx = i;
                <ReferenceForm Entry="@references[idx]"
                               Index="idx"
                               ShowRemove="@(references.Count > 2)"
                               OnEntryChanged="e => UpdateReference(idx, e)"
                               OnRemove="() => RemoveReference(idx)" />
            }

            @if (references.Count < 3)
            {
                <button type="button" class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }

            <div class="step-buttons">
                <button class="btn-back" @onclick="() => currentStep--">Back</button>
                <button class="btn-next" @onclick="NextFromReferences">Next</button>
            </div>
        </section>
    }
    else if (currentStep == 3)
    {
        @* Step 4: Cover Letter *@
        <section class="step-content">
            <h2>Cover Letter</h2>

            <div class="form-group">
                <textarea rows="12" maxlength="2000" @bind="coverLetter" @bind:event="oninput"></textarea>
                <div class="char-count">@coverLetter.Length / 2000 characters</div>
            </div>

            <div class="step-buttons">
                <button class="btn-back" @onclick="() => currentStep--">Back</button>
                <button class="btn-next" @onclick="() => currentStep++">Next</button>
            </div>
        </section>
    }
    else if (currentStep == 4)
    {
        @* Step 5: Review & Submit *@
        <section class="step-content">
            @if (submittedId.HasValue)
            {
                <div class="confirmation">
                    <h2>&#10003; Application Submitted!</h2>
                    <p>Your application ID is: <strong>@submittedId.Value</strong></p>
                    <p>Thank you for applying. We will be in touch soon.</p>
                </div>
            }
            else
            {
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl>
                        <dt>Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-item">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var r in references)
                    {
                        <div class="review-item">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="cover-letter-preview">@coverLetter</p>
                </div>

                <div class="step-buttons">
                    <button class="btn-back" @onclick="() => currentStep--">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @(isSubmitting ? "Submitting..." : "Submit Application")
                    </button>
                </div>
            }
        </section>
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep;
    private string errorMessage = string.Empty;
    private bool isValidating;
    private bool isSubmitting;
    private int? submittedId;

    // Step 1
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
            errorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(email);
            if (!isValid)
            {
                errorMessage = "The email address is not valid. Please check and try again.";
                return;
            }
            currentStep++;
        }
        finally
        {
            isValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        errorMessage = string.Empty;

        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Please fill in company name and job title for all positions.";
                return;
            }
        }

        currentStep++;
    }

    private void NextFromReferences()
    {
        errorMessage = string.Empty;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                errorMessage = "Please fill in name, relationship, and email for all references.";
                return;
            }
        }

        currentStep++;
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());
    private void RemoveWorkEntry(int index) => workEntries.RemoveAt(index);
    private void UpdateWorkEntry(int index, WorkEntryModel updated) => workEntries[index] = updated;

    private void AddReference() => references.Add(new ReferenceModel());
    private void RemoveReference(int index) => references.RemoveAt(index);
    private void UpdateReference(int index, ReferenceModel updated) => references[index] = updated;

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        errorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}
