toolArgs.file_text:
.application-form {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step-item {
    flex: 1;
    text-align: center;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    padding: 0.5rem;
    border: none;
    background: none;
    width: 100%;
    cursor: default;
    font-size: 0.85rem;
}

button.step-button.completed {
    cursor: pointer;
    color: #16a34a;
}

.step-button .step-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: bold;
    border: 2px solid #d1d5db;
    background: #f9fafb;
}

.step-item.completed .step-icon {
    background: #16a34a;
    color: white;
    border-color: #16a34a;
}

.step-item.active .step-icon {
    background: #2563eb;
    color: white;
    border-color: #2563eb;
}

.step-item.future .step-icon {
    opacity: 0.5;
}

.step-item.future .step-label {
    opacity: 0.5;
}

/* Form styles */
.step-content {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.25rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.btn-next, .btn-submit {
    padding: 0.6rem 1.5rem;
    background: #2563eb;
    color: white;
    border: none;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.95rem;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #1d4ed8;
}

.btn-next:disabled, .btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.6rem 1.5rem;
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-back:hover {
    background: #e5e7eb;
}

.btn-add {
    padding: 0.5rem 1rem;
    background: none;
    border: 1px dashed #9ca3af;
    border-radius: 0.375rem;
    cursor: pointer;
    color: #6b7280;
    margin-top: 0.5rem;
}

.btn-add:hover {
    border-color: #2563eb;
    color: #2563eb;
}

.btn-remove {
    padding: 0.25rem 0.75rem;
    background: #fef2f2;
    color: #dc2626;
    border: 1px solid #fecaca;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-edit {
    padding: 0.25rem 0.75rem;
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

/* Cards */
.work-entry-card, .reference-card {
    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f9fafb;
}

.work-entry-header, .reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.work-entry-header h4, .reference-header h4 {
    margin: 0;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

/* Error */
.error-message {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
}

/* Review */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
}

.review-item {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-item:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9fafb;
    padding: 0.75rem;
    border-radius: 0.375rem;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h2 {
    color: #16a34a;
}

